{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260923T221316Z/cell-TD1Be8/src/values.js","content":"/**
 * The value types a cell can hold: a number, some text, a boolean, or one of
 * the six error tokens. Every evaluation function in this program returns
 * one of these tagged objects instead of throwing, so errors flow through
 * the sheet the same way any other value does.
 */

export function num(v) {
  return { k: 'num', v }
}

export function text(v) {
  return { k: 'text', v }
}

export function bool(v) {
  return { k: 'bool', v }
}

export function err(token) {
  return { k: 'err', v: token }
}

/** The error tokens a literal cell may spell out verbatim. */
export const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

/**
 * Reads a value as a number for an arithmetic position: booleans become 1 or
 * 0, text becomes `#VALUE!`, and an existing error passes through.
 */
export function asNumber(v) {
  if (v.k === 'err') return { err: v }
  if (v.k === 'num') return { num: v.v }
  if (v.k === 'bool') return { num: v.v ? 1 : 0 }
  return { err: err('#VALUE!') }
}

/** Type rank for cross-kind comparisons: number < text < boolean. */
function typeRank(v) {
  if (v.k === 'num') return 0
  if (v.k === 'text') return 1
  return 2
}

/** Compares two non-error values per the cross-kind and same-kind rules. */
export function compareValues(l, r) {
  const rl = typeRank(l)
  const rr = typeRank(r)
  if (rl !== rr) return rl < rr ? -1 : 1
  if (l.k === 'num') return l.v < r.v ? -1 : l.v > r.v ? 1 : 0
  if (l.k === 'text') return l.v < r.v ? -1 : l.v > r.v ? 1 : 0
  const a = l.v ? 1 : 0
  const b = r.v ? 1 : 0
  return a < b ? -1 : a > b ? 1 : 0
}
"}

