{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260923T221316Z/cell-TD1Be8/src/address.js","content":"/**
 * Cell addresses: one or two letters for the column, one to three digits for
 * the row. Columns run A..Z, AA..ZZ (base-26, 1-indexed); rows are read as
 * plain numbers, so a leading zero doesn't create a new address.
 */

const ADDRESS_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/**
 * Parses a word as a cell address. Returns null when the word isn't shaped
 * like an address at all, or when it names a row below 1 -- both cases the
 * spec treats as "outside the addressable range".
 */
export function parseAddress(word) {
  const m = ADDRESS_RE.exec(word)
  if (!m) return null
  const rowNum = parseInt(m[2], 10)
  if (rowNum < 1) return null
  const colLetters = m[1].toUpperCase()
  const colNum = colToNum(colLetters)
  return { colNum, rowNum, canonical: colLetters + String(rowNum) }
}

function colToNum(letters) {
  let n = 0
  for (const c of letters) n = n * 26 + (c.charCodeAt(0) - 64)
  return n
}

function numToCol(n) {
  let s = ''
  while (n > 0) {
    const rem = (n - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

/**
 * Expands a range given by its two corner words into the list of addresses
 * it covers, in ascending column and then ascending row order. Returns null
 * when either corner isn't a valid address.
 */
export function expandRange(fromWord, toWord) {
  const a = parseAddress(fromWord)
  const b = parseAddress(toWord)
  if (!a || !b) return null
  const colMin = Math.min(a.colNum, b.colNum)
  const colMax = Math.max(a.colNum, b.colNum)
  const rowMin = Math.min(a.rowNum, b.rowNum)
  const rowMax = Math.max(a.rowNum, b.rowNum)
  const cells = []
  for (let col = colMin; col <= colMax; col++) {
    for (let row = rowMin; row <= rowMax; row++) {
      cells.push(numToCol(col) + row)
    }
  }
  return cells
}

/** Sorts canonical addresses by ascending column, then ascending row. */
export function compareAddresses(a, b) {
  const pa = parseAddress(a)
  const pb = parseAddress(b)
  if (pa.colNum !== pb.colNum) return pa.colNum - pb.colNum
  return pa.rowNum - pb.rowNum
}
"}

