export function parseLiteral(content) {
  if (content === '') return num(0)
  if (LITERAL_NUMBER_RE.test(content)) return num(Number(content))
  if (ERROR_TOKENS.includes(content)) return err(content)
  return text(content)
}

/** Parses a cell's raw content once, caching the result on the record. */
function getParsed(rec) {
  if (rec.parsed) return rec.parsed
  let parsed
  if (rec.content.startsWith('=')) {
    parsed = { kind: 'formula', ast: parseFormula(rec.content.slice(1)) }
  } else {
    parsed = { kind: 'literal', value: parseLiteral(rec.content) }
  }
  rec.parsed = parsed
  return parsed
}

/**
 * Evaluates the cell at a canonical address, memoizing across the whole
 * sheet and detecting cycles via a stack of addresses under evaluation.
 * An address still on the stack yields `#CYCLE!` for that reference; the
 * cells actually on the cycle end up `#CYCLE!` themselves once the error
 * propagates back through their own formulas.
 */
export function evalCell(addr, ctx) {
  if (ctx.memo.has(addr)) return ctx.memo.get(addr)
  if (ctx.stack.has(addr)) return err('#CYCLE!')
  const rec = ctx.sheet.get(addr)
  if (!rec) {
    const v = num(0)
    ctx.memo.set(addr, v)
    return v
