  ctx.stack.add(addr)
  const parsed = getParsed(rec)
  const value = parsed.kind === 'literal' ? parsed.value : parsed.ast ? evalNode(parsed.ast, ctx) : err('#ERR!')
  ctx.stack.delete(addr)
  ctx.memo.set(addr, value)
