  switch (node.type) {
    case 'num':
      return num(node.value)
    case 'bool':
      return bool(node.value)
    case 'address': {
      const info = evalAddressNode(node)
      if (!info) return err('#REF!')
      return evalCell(info.canonical, ctx)
