    const condVals = evalArgument(args[0], ctx)
    const condErr = condVals.find((v) => v.k === 'err')
    if (condErr) return condErr
    const cond = toCondition(condVals[0])
    if (cond.err) return cond.err
    const branch = cond.bool ? args[1] : args[2]
    // Only the taken branch is evaluated, so an error (or cycle) in the
    // branch not taken is invisible.
    const vals = evalArgument(branch, ctx)
    return vals[0]
  }
