    if (args.length !== 1) return err('#ERR!')
    const vals = evalArgument(args[0], ctx)
    const firstErr = vals.find((v) => v.k === 'err')
    if (firstErr) return firstErr
    const n = asNumber(vals[0])
    if (n.err) return n.err
    return num(Math.abs(n.num))
