    for (const v of allVals) {
      if (v.k === 'err') return v
      if (v.k === 'num') count++
    }
    return num(count)
  }
  const nums = []
  for (const v of allVals) {
    if (v.k === 'err') return v
    const n = asNumber(v)
    if (n.err) return n.err
    nums.push(n.num)
  }
  let result
  switch (name) {
    case 'SUM':
      result = nums.reduce((s, x) => s + x, 0)
      break
    case 'AVG':
      result = nums.reduce((s, x) => s + x, 0) / nums.length
      break
    case 'MIN':
      result = Math.min(...nums)
      break
    case 'MAX':
      result = Math.max(...nums)
