/** Collects every cell a parsed formula names directly, ranges expanded. */
export function collectDeps(ast) {
  const set = new Set()
  walk(ast)
  return [...set].sort(compareAddresses)

  function walk(node) {
    switch (node.type) {
      case 'num':
      case 'bool':
        return
      case 'address': {
        const info = parseAddress(node.name)
        if (info) set.add(info.canonical)
        return
      }
      case 'unary':
        walk(node.operand)
        return
      case 'binop':
        walk(node.left)
        walk(node.right)
        return
      case 'call':
        for (const a of node.args) walkArgument(a)
        return
      default:
        throw new Error('unreachable node type ' + node.type)
    }
  }

