 * a SheetError carrying the line-numbered message the CLI reports on a
 * failure; the caller decides how to present it.
 */
export function parseSheet(input) {
  const lines = input.length === 0 ? [] : input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const sheet = new Map()
  lines.forEach((line, i) => {
    const lineNo = i + 1
    const stripped = line.replace(/^[ \t]*/, '')
    if (stripped === '' || stripped.startsWith('#')) return

    const m = /^(\S+)/.exec(stripped)
    const addrToken = m[1]
    const rest = stripped.slice(addrToken.length).replace(/^[ \t]+/, '')

    const info = parseAddress(addrToken)
    if (!info) throw new SheetError(`error: line ${lineNo}: invalid cell address ${addrToken}`)
    if (sheet.has(info.canonical)) {
      throw new SheetError(`error: line ${lineNo}: cell ${info.canonical} is declared twice`)
    }
    sheet.set(info.canonical, { content: rest, colNum: info.colNum, rowNum: info.rowNum })
  })

  return sheet
}

/** Declared addresses in ascending column, then ascending row order. */
export function orderedAddresses(sheet) {
  return [...sheet.keys()].sort(compareAddresses)
}

export { SheetError }
"}

