/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { readFileSync } from 'node:fs'
import { parseSheet, orderedAddresses, SheetError } from './sheet.js'
import { evalCell, getParsed, collectDeps } from './evaluate.js'
import { formatValue } from './format.js'

function fail(message) {
  process.stderr.write(message + '\n')
  process.exit(2)
}

function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'values' && argv[0] !== 'deps')) {
    fail('error: usage: cli.js values|deps')
  }
  const mode = argv[0]

  const input = readFileSync(0, 'utf8')
  let sheet
  try {
    sheet = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) fail(e.message)
    throw e
  }

  const addrs = orderedAddresses(sheet)
  const out = []

  if (mode === 'values') {
    const ctx = { sheet, memo: new Map(), stack: new Set() }
    for (const addr of addrs) {
      out.push(`${addr}=${formatValue(evalCell(addr, ctx))}\n`)
    }
  } else {
    for (const addr of addrs) {
      const rec = sheet.get(addr)
      const parsed = getParsed(rec)
      const deps = parsed.kind === 'formula' && parsed.ast ? collectDeps(parsed.ast) : []
      out.push(`${addr}:${deps.map((d) => ' ' + d).join('')}\n`)
    }
  }

  process.stdout.write(out.join(''))
  process.exit(0)
}

main()
"}

